 ('x25-menu-joint-buttons.png', 'Menu of a point load on a truss diagonal 4.24 m long. 4.25 m typed as its place: the load stands on the joint and the menu says so. Two buttons set the load on a joint of its member', 'truss', "m.loads = [{id: 1, m: 9, a: 2, P: 20, ang: -90}]", 'M', "const L = __lab; let hit = null; for (let y = 0; y < 700 && !hit; y += 3) for (let x = 100; x < 1100; x += 3) { const h = L.pick(x, y); if (h && h.type === 'load') { hit = [x, y]; break; } } const c = document.querySelector('canvas').getBoundingClientRect(); return { click: [c.x + hit[0], c.y + hit[1]], type: ['#pp-a', '4.25'] };", 1500, 900, 'light'),
