 ('x51-frame-probe-displacement.png', 'Sway portal — tab deflection, the probe on the beam: δ is the displacement of the point, w its part across the member and θ the rotation of the member there', 'portal-s', '', 'D', "const c = document.querySelector('canvas').getBoundingClientRect(); const g = __lab.MG[1]; return [c.x + g.ax + (g.bx - g.ax) * 0.3, c.y + g.ay + (g.by - g.ay) * 0.3];", 1500, 900, 'light'),
 ('x52-far-corner-portal.png', 'Portal frame with columns of 0.50 m of HEB 300 under a beam of 30.00 m of IPE 200 (section 7.72): the far corner of what the menus allow. The hand formulas and the analysis agree; the panel says that the displacement lies outside the theory of the page', 'portal-g', "m.members[0].sec = m.members[2].sec = 6; L.stretch(m, 'y', 0, 4, 0.5); L.stretch(m, 'x', 0, 8, 30); const s_ = document.querySelector('#sec'); s_.value = '0'; s_.dispatchEvent(new Event('change'))", 'M', '', 1500, 900, 'light'),
 ('x53-truss-other-panel.png', 'Truss with a height of 4.50 m and a second panel of 6.00 m (section 7.73) — tab axial force: the cut of the method of sections lies in its panel and the card uses the lengths of the drawing', 'truss', "L.stretch(m, 'y', 0, 3, 4.5); L.stretch(m, 'x', 3, 6, 6)", 'N', '', 1500, 900, 'light'),
 ('x54-overhang-bent-by-its-length.png', 'Span of 30.00 m with B fixed and an overhang of 1.40 m, IPE 200, with 6400 kN at its end (section 7.77) — tab deflection: the end moves 1 434.7 mm, less than a twentieth of the span and more than the overhang is long. The card “Large displacement” names the member B–C and gives its rotation, 1537.1 mrad', 'overhang', "const s_ = document.querySelector('#sec'); s_.value = '0'; s_.dispatchEvent(new Event('change')); m.members.forEach(k => k.udl.on = false); L.stretch(m, 'x', 5, 7, 1.4); L.stretch(m, 'x', 0, 5, 30); m.nodes.find(n => n.lbl === 'B').sup = 'fixed'; m.loads = []; for (let i = 0; i < 6; i++) m.loads.push({id: 10 + i, m: 1, a: 1.4, P: 1000, ang: -90}); m.loads.push({id: 99, m: 1, a: 1.4, P: 400, ang: -90})", 'D', '', 1500, 900, 'light'),
 ('x55-load-along-the-beam-on-a-zero-of-the-shear.png', 'Simple beam with 10 kN/m and 20 kN along the beam at midspan (section 7.75): the load along the beam makes no step in the shear, and the peak of 45.0 kNm carries the mark of a zero of the shear, “V = 0: peak of M”', 'simple-w', 'm.loads = [{id: 1, m: 0, a: 3, P: 20, ang: 0}]', 'M', '', 1500, 900, 'light'),
 ('x56-axial-step-at-a-roller.png', 'Two-span beam with a pin at A, rollers at B and C and 20 kN to the right on B (section 7.76) — tab axial force: N is 20 kN left of B and zero right of it. The rule “at a joint” gives the step with its sign: N right of B = N left of B − (F_x + P_x) = 20 − (0 + 20)', 'two-span', "m.nodes.forEach(n => { n.sup = n.lbl === 'A' ? 'pin' : 'roller'; }); m.members.forEach(k => k.udl.on = false); m.loads = [{id: 1, m: 0, a: 5, P: 20, ang: 0}]", 'N', '', 1500, 900, 'light'),
 ('x57-compare-kept-ends-of-a-frame-bar.png', 'Portal with hinged corners, “Compare” on: the kept state had 10 kN/m to the right along the beam, now 5 kN/m act downward on it — tab axial force. The beam has no axial force now; its kept force is drawn dashed, with 40.0 and −40.0 in brackets at its two ends', 'portal-g', 'm.nodes[1].hinge = m.nodes[2].hinge = true; m.members.forEach(k => k.udl.on = false); Object.assign(m.members[1].udl, {on: true, w1: 10, w2: 10, ang: 0})', 'N', "document.querySelector('#cmp').click(); Object.assign(__lab.st.model.members[1].udl, {on: true, w1: 5, w2: 5, ang: -90}); __lab.resolve('tween');", 1500, 900, 'light'),
 ('x58-menu-single-member-section.png', 'Simple beam, menu of its one member: the choice of the section is that of the header and is named “Section”; the menu says that it stays when the example is reset or another one is picked', 'simple-w', '', 'D', "document.querySelector('#loads').click();", 1500, 900, 'light'),
 ('x59-place-typed-as-rounded-length.png', 'Menu of a point load on a truss diagonal of 4.243 m with 4.24 typed as its place: the load stands inside the member, 2.6 mm before the joint. The menu says so, gives the length with three decimals and points to the button that puts the load on the joint', 'truss', 'm.loads = [{id: 1, m: 9, a: 2, P: 20, ang: -90}]', 'M', "const L = __lab; let hit = null; for (let y = 0; y < 700 && !hit; y += 3) for (let x = 100; x < 1100; x += 3) { const h = L.pick(x, y); if (h && h.type === 'load') { hit = [x, y]; break; } } const c = document.querySelector('canvas').getBoundingClientRect(); return { click: [c.x + hit[0], c.y + hit[1]], type: ['#pp-a', '4.24'] };", 1500, 900, 'light'),
 ('x60-small-deflection-beside-large-axial-force.png', 'Arm of 0.50 m left of the fixed support B with 2 kN on its end, and 95 loads of 1000 kN along the 30.00 m right of B, IPE 200 (section 7.78) — tab deflection: the deflection of 0.02 mm is too small for a number of its own; the rotation of the end is written, −0.1 mrad. The line is drawn and is not called zero. The horizontal reaction of the fixed support stands below the beam', 'overhang', "const s_ = document.querySelector('#sec'); s_.value = '0'; s_.dispatchEvent(new Event('change')); m.members.forEach(k => k.udl.on = false); L.stretch(m, 'x', 5, 7, 30); L.stretch(m, 'x', 0, 5, 0.5); m.nodes.forEach(n => { n.sup = n.lbl === 'B' ? 'fixed' : 'free'; }); m.loads = [{id: 1, m: 0, a: 0, P: 2, ang: -90}]; for (let i = 0; i < 95; i++) m.loads.push({id: 10 + i, m: 1, a: 30, P: 1000, ang: 0})", 'D', '', 1500, 900, 'light'),
 ('x61-probe-at-a-load-beside-a-peak.png', '492.3 kN/m and 949.9 kN at 2.27 m (section 7.60), the probe at the load: the peak of the moment lies a third of a micrometre behind the load, on the same pixel. The probe stands on the load and gives the shear on its two sides, 949.9 and 0.0 kN', 'simple-p', 'Object.assign(m.members[0].udl, {on: true, w1: 492.3, w2: 492.3, ang: -90}); m.loads = [{id: 1, m: 0, a: 2.27, P: 949.9, ang: -90}]', 'M', "const c = document.querySelector('canvas').getBoundingClientRect(), V = __lab.VW; return [c.x + V.ox + 2.27 * V.s + 1, c.y + V.yB + 140];", 1500, 900, 'light'),
 ('x7-phone.png', 'Width of a phone (400 px): the window of the section, folded, and the panel follow below the drawing', 'simple-t', '', 'M', '', 400, 800, 'light'),
 ('x7b-phone-truss.png', 'Truss at the width of a phone', 'truss', '', 'N', '', 400, 800, 'light'),
 ('x8-dark.png', 'Dark colours; the page follows the setting of the system', 'two-span', '', 'M', '', 1500, 900, 'dark'),
 # version 15: the points of review 10 (at the end, so that the numbers of the earlier screens stay)
 ('x62-short-stretch-that-turns-far.png', 'Cantilever of 30.00 m, IPE 200, with 500 kN downward at 26 m, 1000 kN upward at 28 m and 500 kN downward at 30 m (section 7.80) — tab deflection: the end moves 980.3 mm, less than a twentieth of the length, and turns by 490.2 mrad. The card “Large displacement” goes by the largest rotation of a member and stands', 'cantilever', "const s_ = document.querySelector('#sec'); s_.value = '0'; s_.dispatchEvent(new Event('change')); L.stretch(m, 'x', 0, 3, 30); m.members.forEach(k => k.udl.on = false); m.loads = [{id: 1, m: 0, a: 26, P: 500, ang: -90}, {id: 2, m: 0, a: 28, P: 1000, ang: 90}, {id: 3, m: 0, a: 30, P: 500, ang: -90}]", 'D', '', 1500, 900, 'light'),
 ('x63-bar-stretched-by-a-twentieth.png', 'Bent cantilever, IPE 200, with a hinge at B and a roller at C; the arm B–C is pulled by 30 loads of 1000 kN at each end (section 7.81) — tab displacement: the arm is a bar and is stretched by 150.4 mm, 5.01 % of its length. The card “Large displacement” says that the member is stretched by 5.0 % over its whole length and names no rotation', 'bent', "const s_ = document.querySelector('#sec'); s_.value = '0'; s_.dispatchEvent(new Event('change')); m.nodes[1].hinge = true; m.nodes[2].sup = 'roller'; m.members.forEach(k => k.udl.on = false); m.loads = []; for (let i = 0; i < 30; i++) { m.loads.push({id: 10 + i, m: 1, a: 0, P: 1000, ang: 180}); m.loads.push({id: 100 + i, m: 1, a: 3, P: 1000, ang: 0}); }", 'D', '', 1500, 900, 'light'),
 ('x64-low-point-on-the-card-of-a-roof.png', 'Portal with fixed feet, 40 kN/m inward on each column and 1.5 kN/m on the roof (section 7.82) — tab shear, the pointer on the roof: the roof has −17.1 kNm at its ends and −5.1 kNm at its middle. Its card, brought into view in the panel, says that M has a low point where V = 0. The line of the heights stands right of the value of the load on the right column', 'portal-g', "m.nodes.forEach(n => { if (n.sup && n.sup !== 'free') n.sup = 'fixed'; }); m.loads = []; m.members.forEach(k => k.udl.on = false); Object.assign(m.members[0].udl, {on: true, w1: 40, w2: 40, ang: 0}); Object.assign(m.members[2].udl, {on: true, w1: 40, w2: 40, ang: 180}); Object.assign(m.members[1].udl, {on: true, w1: 1.5, w2: 1.5, ang: -90})", 'V', "const c = document.querySelector('canvas').getBoundingClientRect(); const g = __lab.MG[1]; return { move: [c.x + g.ax + (g.bx - g.ax) * 0.31, c.y + g.ay + (g.by - g.ay) * 0.31], show: 'how its shear line is built' };", 1500, 900, 'light'),
 ('x66-load-at-a-flat-angle.png', 'Truss with a height of 0.75 m and 100 kN/m to the right on the first diagonal (section 7.83) — tab shear, the pointer on the mark of the load: the load makes 14 degrees with the bar and is drawn beside it. The hint under the drawing says that it also bends the member; the shear at the ends of the bar is 37.5 kN', 'truss', "L.stretch(m, 'y', 0, 3, 0.75); m.loads = []; Object.assign(m.members[9].udl, {on: true, w1: 100, w2: 100, ang: 0})", 'V', "const c = document.querySelector('canvas').getBoundingClientRect(); const u = __lab.HS.udl.get(9); return [c.x + u.kx, c.y + u.ky];", 1500, 900, 'light'),
 ('x67-length-typed-key-by-key.png', 'Simple beam with “Compare” on, menu of the beam with 35 typed into the length field key by key: on the way the field held 3, a length the page takes. With 35 it holds none: the beam is 6.00 m long as before, the load stands at 2.00 m, “Compare” is still on, and the menu says that the length stays 6.00 m', 'simple-p', '', 'M', "document.querySelector('#cmp').click(); document.querySelector('#loads').click(); return { keys: ['#pp-len', '35'] };", 1500, 900, 'light'),
 ('x68-probe-at-a-loaded-joint.png', 'Two-span beam with a pin at A, rollers at B and C and 20 kN to the right on B, held as a load at the start of the right span — tab axial force, the probe at B: both sides, N left 20.0 kN and N right 0.0 kN', 'two-span', "m.nodes.forEach(n => { n.sup = n.lbl === 'A' ? 'pin' : 'roller'; }); m.members.forEach(k => k.udl.on = false); m.loads = [{id: 1, m: 1, a: 0, P: 20, ang: 0}]", 'N', "const c = document.querySelector('canvas').getBoundingClientRect(), V = __lab.VW; return [c.x + V.ox + 5 * V.s + 1, c.y + V.yB + 140];", 1500, 900, 'light'),
 ('x69-ten-centimetres-strained.png', 'Bent cantilever, IPE 200, with a hinge at B and a roller at C; sixty loads of 1000 kN act to the left at 1.00 m of the arm and sixty to the right at 1.10 m (section 7.84) — tab axial force: between the loads the arm carries 60 000 kN and is strained by 10.0 %, while it gets longer by 0.33 % of its length. The card “Large displacement” names that stretch of 10 cm', 'bent', "const s_ = document.querySelector('#sec'); s_.value = '0'; s_.dispatchEvent(new Event('change')); m.nodes[1].hinge = true; m.nodes[2].sup = 'roller'; m.members.forEach(k => k.udl.on = false); m.loads = []; for (let i = 0; i < 60; i++) { m.loads.push({id: 10 + i, m: 1, a: 1, P: 1000, ang: 180}); m.loads.push({id: 200 + i, m: 1, a: 1.1, P: 1000, ang: 0}); }", 'N', '', 1500, 900, 'light'),
 ('x70-size-typed-with-an-exponent.png', 'Simple beam with 20 kN at 2 m, menu of the load with 9000e-1 typed into the size key by key: on the way the field held 9000, more than the page takes. The field keeps the keys; with the last key it holds 900: the load is 900 kN and the largest moment 1200.0 kNm', 'simple-p', 'm.loads[0].a = 2; m.loads[0].P = 20', 'M', "const L = __lab, c = document.querySelector('canvas').getBoundingClientRect(); for (let y = 0; y < 700; y += 3) for (let x = 100; x < 1100; x += 3) { const h = L.pick(x, y); if (h && h.type === 'load') return { click: [c.x + x, c.y + y], keys: ['#pp-P', '9000e-1'] }; } return null;", 1500, 900, 'light'),
 ('x71-kept-values-after-a-hinge-is-closed.png', 'Portal with hinged corners, “Compare” on: the kept state had 10 kN/m to the right along the beam. Now 5 kN/m act downward on it and the hinge at C is closed — tab axial force: the beam is no bar any more and carries −3.9 kN; its kept force is drawn dashed, and 40.0 and −40.0 stay in brackets at its two ends', 'portal-g', 'm.nodes[1].hinge = m.nodes[2].hinge = true; m.members.forEach(k => k.udl.on = false); Object.assign(m.members[1].udl, {on: true, w1: 10, w2: 10, ang: 0})', 'N', "document.querySelector('#cmp').click(); Object.assign(__lab.st.model.members[1].udl, {on: true, w1: 5, w2: 5, ang: -90}); __lab.st.model.nodes[1].hinge = false; __lab.resolve('tween');", 1500, 900, 'light'),
 ('x72-two-loads-that-cancel.png', 'Simple beam with 10 kN/m and, at midspan, 20 kN upward and 20 kN downward (section 7.85) — tab shear: the two loads cancel. The shear line has no step there and the moment line no kink; the card of the member says that loads at one place count together', 'simple-w', 'm.loads = [{id: 1, m: 0, a: 3, P: 20, ang: 90}, {id: 2, m: 0, a: 3, P: 20, ang: -90}]', 'V', '', 1500, 900, 'light'),
 ('x73-load-value-clear-of-a-reaction.png', 'Truss, IPE 200, with 500 kN/m along the first bottom chord and six loads on it (section 7.51) — tab axial force: the value 500.0 kN/m stands below the chord with a hairline to its mark, clear of the reaction 158.9 kN. Up to version 15 it stood on that reaction', 'truss', "const s_ = document.querySelector('#sec'); s_.value = '0'; s_.dispatchEvent(new Event('change')); Object.assign(m.members[0].udl, {on: true, w1: 500, w2: 500, ang: 0}); m.loads = [[0.01, 599.1, 180], [1.52, 4.5, 180], [1.53, 4.5, 180], [2.25, 49.7, 0], [2.99, 599.1, 180], [3, 183.6, 180]].map((l, i) => ({id: 1 + i, m: 0, a: l[0], P: l[1], ang: l[2]}))", 'N', '', 1500, 900, 'light'),
 ('x74-dark-by-the-button.png', 'Portal frame after a click on “Dark”: the dark sheet, on a computer that is set to light. The button stays pressed; the choice is kept for the next visit', 'portal-g', '', 'M', "document.querySelector('#theme').click();", 1500, 900, 'light'), ('x75-rows-of-the-relations.png', 'Simple beam under 10 kN/m, the mouse off the sheet (version 17): under each line stands its relation, the symbols in the colours of their lines, and the same in words: V′ = −q, per metre V changes by −q; M′ = V; w′ = θ and EI·w″ = −M', 'simple-w', '', 'M', '', 1500, 900, 'light'),
 ('x76-rows-with-the-numbers-of-a-place.png', 'Two-span beam, the probe at 3.40 m — tab moment: the rows carry the numbers of that place. The −15.3 kN behind M′ = V is the shear in the box of V; on the moment line a triangle with a base of 1 m shows the same number as the change of M, −15.3 kNm; the row of the deflection has the rotation and −M', 'two-span', '', 'M', "const c = document.querySelector('canvas').getBoundingClientRect(), V = __lab.VW; return [c.x + V.ox + 3.4 * V.s, c.y + V.yB + 150];", 1500, 900, 'light'),
 ('x77-row-at-a-support.png', 'Two-span beam, the probe at the inner support — tab shear: the row under the shear line says that V steps by the reaction, +62.5 kN, and changes by −10.0 kN per metre; the row under the moment line has the shear on both sides', 'two-span', '', 'V', "const c = document.querySelector('canvas').getBoundingClientRect(), V = __lab.VW; return [c.x + V.ox + 5 * V.s, c.y + V.yB + 150];", 1500, 900, 'light'),
 ('x78-row-at-a-hinge.png', 'Gerber beam, the probe at the hinge G — tab deflection: the rotation on both sides of the hinge, −0.6 | 0.9 mrad, with the triangle on the deflection line to the right of it', 'gerber', '', 'D', "const c = document.querySelector('canvas').getBoundingClientRect(), V = __lab.VW; return [c.x + V.ox + 7.5 * V.s, c.y + V.yB + 150];", 1500, 900, 'light'),
 ('x79-row-of-a-frame.png', 'Portal frame, the mouse on the beam at 2.40 m — tab moment: one row under the structure, M′ = V = 24.0 kN, the shear of that place as the box lists it', 'portal-g', '', 'M', "const c = document.querySelector('canvas').getBoundingClientRect(), g = __lab.MG[1]; return [c.x + g.ax + (g.bx - g.ax) * 0.3, c.y + g.ay + (g.by - g.ay) * 0.3];", 1500, 900, 'light'),
 ('x80-four-rows.png', 'Simple beam with 20 kN at 45 degrees — tab axial force, the probe at 4.00 m: four lines, each with its row; N′ = −n', 'simple-p', 'm.loads = [{ id: 1, m: 0, a: 2, P: 20, ang: -45 }]', 'N', "const c = document.querySelector('canvas').getBoundingClientRect(), V = __lab.VW; return [c.x + V.ox + 4 * V.s, c.y + V.yB + 150];", 1500, 900, 'light'),
 ('x81-rows-dark.png', 'The rows on the dark sheet: two-span beam, the probe at 1.50 m — tab moment', 'two-span', '', 'M', "document.querySelector('#theme').click(); const c = document.querySelector('canvas').getBoundingClientRect(), V = __lab.VW; return [c.x + V.ox + 1.5 * V.s, c.y + V.yB + 150];", 1500, 900, 'light'),
 ('x82-no-rows-on-a-narrow-sheet.png', 'A sheet of 400 px has no rows: the relation stands in the corner of its strip, in the colours of its lines, and its number in the box of the probe (M′ = V with 15.0 kN at 1.50 m)', 'simple-w', '', 'M', "const c = document.querySelector('canvas').getBoundingClientRect(), V = __lab.VW; return [c.x + V.ox + 1.5 * V.s, c.y + V.yB + 150];", 400, 800, 'light'),
 ('x83-3d-beam-cut.png', 'The 3D view (version 18), simple beam under 10 kN/m with the probe at 2.00 m — tab moment. Above: the beam as a body with the outline of its IPE 300, its supports, the load and the moment line as a clear sheet, bent by the factor of the sheet and coloured by its normal stress. Below: the beam cut at that place, with the body of the normal stress on the cut face, −71.8 N/mm² at the top and +71.8 at the bottom', 'simple-w', '', 'M', "document.querySelector('#v3d').click(); const c = document.querySelector('#cv').getBoundingClientRect(), V = __lab.VW; return new Promise(r => setTimeout(() => { const c2 = document.querySelector('#cv').getBoundingClientRect(), W = __lab.VW; r([c2.x + W.ox + 2 * W.s, c2.y + W.yB + 150]); }, 700));", 1500, 900, 'light'),
 ('x84-3d-support-of-a-two-span-beam.png', 'The 3D view, two-span beam with the probe at the inner support — tab moment: the moment is negative there, so the top is in tension (arrows away from the cut face) and the bottom in compression', 'two-span', '', 'M', "document.querySelector('#v3d').click(); const c = document.querySelector('#cv').getBoundingClientRect(), V = __lab.VW; return new Promise(r => setTimeout(() => { const c2 = document.querySelector('#cv').getBoundingClientRect(), W = __lab.VW; r([c2.x + W.ox + 5 * W.s, c2.y + W.yB + 150]); }, 700));", 1500, 900, 'light'),
 ('x85-3d-portal-frame.png', 'The 3D view, portal frame with the mouse on the beam at 2.40 m — tab moment: N = −24.0 kN and M = 36.8 kNm give −70.5 N/mm² at the top and +61.6 at the bottom; the fibre without stress lies above the middle', 'portal-g', '', 'M', "document.querySelector('#v3d').click(); return new Promise(r => setTimeout(() => { const c = document.querySelector('#cv').getBoundingClientRect(), g = __lab.MG[1]; r([c.x + g.ax + (g.bx - g.ax) * 0.3, c.y + g.ay + (g.by - g.ay) * 0.3]); }, 700));", 1500, 900, 'light'),
 ('x86-3d-truss.png', 'The 3D view, truss with the mouse on a bottom chord — tab axial force: the bars in the colours of their stress, compression and tension; the bar cut open carries N/A = +5.6 N/mm² at every fibre', 'truss', '', 'N', "document.querySelector('#v3d').click(); return new Promise(r => setTimeout(() => { const c = document.querySelector('#cv').getBoundingClientRect(), g = __lab.MG[3]; r([c.x + g.ax + (g.bx - g.ax) * 0.5, c.y + g.ay + (g.by - g.ay) * 0.5]); }, 700));", 1500, 900, 'light'),
 ('x87-3d-dark-sway-frame.png', 'The 3D view on the dark sheet in a window of 1280 px: portal with pinned feet under a side load, the mouse on the left column — tab displacement. The sheet beside it keeps 640 px', 'portal-s', '', 'D', "document.querySelector('#theme').click(); document.querySelector('#v3d').click(); return new Promise(r => setTimeout(() => { const c = document.querySelector('#cv').getBoundingClientRect(), g = __lab.MG[0]; r([c.x + g.ax + (g.bx - g.ax) * 0.5, c.y + g.ay + (g.by - g.ay) * 0.5]); }, 700));", 1280, 800, 'light'),
 ('x90-3d-shear-stress.png', 'The 3D view, two-span beam with the probe at 4.50 m — tab shear: the cut shows the shear stress. Its body stands on the web, largest at the middle with τ = V·S/(I·t) = 13.9 N/mm² for V = −26.3 kN, and low on the flanges; the arrow on the face shows which way it acts. The shear line stands as a sheet in the plane of the beam', 'two-span', '', 'V', "document.querySelector('#v3d').click(); const c = document.querySelector('#cv').getBoundingClientRect(), V = __lab.VW; return new Promise(r => setTimeout(() => { const c2 = document.querySelector('#cv').getBoundingClientRect(), W = __lab.VW; r([c2.x + W.ox + 4.5 * W.s, c2.y + W.yB + 150]); }, 700));", 1500, 900, 'light'),
 ('x88-3d-wide.png', 'The 3D view in a window of 1920 x 1080: Gerber beam with the probe at 4.00 m — tab moment', 'gerber', '', 'M', "document.querySelector('#v3d').click(); const c = document.querySelector('#cv').getBoundingClientRect(), V = __lab.VW; return new Promise(r => setTimeout(() => { const c2 = document.querySelector('#cv').getBoundingClientRect(), W = __lab.VW; r([c2.x + W.ox + 4 * W.s, c2.y + W.yB + 150]); }, 700));", 1920, 1080, 'light'),
 ('x89-3d-on-a-phone.png', 'A sheet of 400 px with the 3D view on: it stands under the sheet (the page is moved to it here)', 'simple-w', '', 'M', "document.querySelector('#v3d').click(); return new Promise(r => setTimeout(() => { document.querySelector('#v3').scrollIntoView(); r(null); }, 600));", 400, 800, 'light'),
 ('x91-turn-of-the-deflection.png', 'Version 19, simple beam of 6 m with 20 kN at 2.00 m on the dark sheet — tab moment. The moment has its peak under the load; the deflection has its peak at 2.73 m, where the rotation is zero. A flat dashed tangent with a dot marks that turn and the note says “θ = 0: peak of w”. The line carries 4.4 mm there and 4.1 mm under the load', 'simple-p', "m.loads = [{ id: 1, m: 0, a: 2, P: 20, ang: -90 }]", 'M', "document.querySelector('#theme').click();", 1500, 900, 'light'),
 ('x92-turn-read-by-the-probe.png', 'The same beam with the probe beside the turn, at 2.75 m — tab deflection: the row under the line reads w′ = θ = 0.0 mrad, and the box 4.4 mm', 'simple-p', "m.loads = [{ id: 1, m: 0, a: 2, P: 20, ang: -90 }]", 'D', "const c = document.querySelector('canvas').getBoundingClientRect(), V = __lab.VW, p = V.plots.find(q => q.k === 'D'); return [c.x + V.ox + 2.75 * V.s, c.y + p.y + p.h / 2];", 1500, 900, 'light'),
