errs = []
with sync_playwright() as p:
    b = p.chromium.launch(executable_path=__import__('os').environ.get('CHROME') or None, args=['--no-sandbox'])
    for f, cap, pid, js, tab, after, w, h, scheme in S:
        pg = b.new_page(viewport={'width': w, 'height': h}, device_scale_factor=1, color_scheme=scheme)
        pg.on('pageerror', lambda e: errs.append(str(e)))
        pg.goto(url); pg.wait_for_timeout(500)
        pg.click(f'.pre[data-id="{pid}"]'); pg.wait_for_timeout(300)
        if js: pg.evaluate("() => { const L = __lab, m = L.st.model; " + js + "; L.resolve('grow'); }")
        if tab: pg.click(f'#tab-{tab}')
        pg.wait_for_timeout(1100)
        r = None
        if after: r = pg.evaluate("() => { " + after + " }"); pg.wait_for_timeout(1300)
        # the step can ask for the mouse at a place (a probe), or for a click, with or without an entry in a field
        if isinstance(r, list): pg.mouse.move(r[0], r[1]); pg.wait_for_timeout(500)
        elif isinstance(r, dict):
            if 'move' in r: pg.mouse.move(*r['move']); pg.wait_for_timeout(500)   # the mouse at a place, then a card of the panel brought into view
            if 'show' in r: pg.evaluate("(t) => { const c = [...document.querySelectorAll('#learn .card')].find(x => x.textContent.includes(t)); if (c) c.scrollIntoView({ block: 'center' }); }", r['show']); pg.wait_for_timeout(300)
            if 'click' in r: pg.mouse.click(*r['click']); pg.wait_for_timeout(400)
            if 'type' in r: pg.fill(*r['type']); pg.wait_for_timeout(300)
            if 'keys' in r: pg.click(r['keys'][0]); pg.keyboard.press('Control+a'); pg.keyboard.type(r['keys'][1], delay=120); pg.wait_for_timeout(400)   # typed key by key
        else: pg.mouse.move(5, 5); pg.wait_for_timeout(150)
        pg.screenshot(path=str(out / f)); pg.close()
    b.close()
(out / 'manifest.json').write_text(json.dumps([[s[0], s[1]] for s in S], ensure_ascii=False, indent=1))
print(len(S), 'screens;', '; '.join(errs) if errs else 'no script errors')
sys.exit(1 if errs else 0)
